MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var rnd = MC.rng(1337);
  var title = String(v.title || "").toUpperCase();
  var sub = String(v.subtitle || "").trim();
  var palette = ["var(--grass)", "var(--gold)", "var(--diamond)", "var(--redstone)", "var(--amethyst)"];

  // --- title layout (pre-computed, font-load independent)
  var K = 0.53;
  var fit = MC.fit(title, d.vertical
    ? { maxWidth: W * 0.88, maxSize: 96, minSize: 30, k: K, maxLines: 3, maxHeight: H * 0.34 }
    : { maxWidth: W * 0.86, maxSize: 112, minSize: 30, k: K, maxLines: 2, maxHeight: H * 0.42 });
  var tEl = document.getElementById("tt-title");
  tEl.style.fontSize = fit.size + "px";
  var parts = MC.renderLines(tEl, fit.lines);
  var titleH = fit.lines.length * fit.size;
  var longest = Math.max.apply(null, fit.lines.map(function (l) { return l.length; }));
  var titleW = longest * fit.size * K;
  var cy = H * (d.vertical ? 0.42 : 0.43);
  var titleTop = cy - titleH / 2 - (sub ? 24 : 0);
  tEl.style.top = titleTop + "px";

  // --- block plinth under the title: two staggered rows
  var B = d.vertical ? 40 : 42;
  var plinthW = Math.min(W * 0.92, Math.max(titleW + B * 2, B * 6));
  var cols = Math.max(4, Math.round(plinthW / B));
  var plinthTop = titleTop + titleH + fit.size * 0.22;
  var x0 = W / 2 - (cols * B) / 2;
  var bWrap = document.getElementById("tt-blocks");
  var blocks = [], targets = [];
  for (var r = 0; r < 2; r++) {
    var n = r === 0 ? cols : cols - 1;
    for (var c = 0; c < n; c++) {
      var b = document.createElement("div");
      b.className = "mc-block";
      b.style.width = B + "px"; b.style.height = B + "px";
      b.style.left = (x0 + c * B + (r === 1 ? B / 2 : 0)) + "px";
      b.style.top = (plinthTop + r * B) + "px";
      b.style.setProperty("--bc", r === 0 ? palette[(c * 2 + 1) % palette.length] : "var(--ink)");
      if (r === 1) b.style.borderColor = "#000";
      bWrap.appendChild(b);
      blocks.push(b);
      targets.push({ dx: (rnd() - 0.5) * W * 0.5, dy: -(H * 0.6 + rnd() * H * 0.4), rot: (rnd() - 0.5) * 200, delay: rnd() * 0.5 + r * 0.12 });
    }
  }

  // --- subtitle tag on the plinth
  var sEl = document.getElementById("tt-sub");
  if (sub) {
    sEl.textContent = sub.toUpperCase();
    var sSize = d.vertical ? 30 : 30;
    sSize = Math.min(sSize, (W * 0.8) / (sub.length * 0.62));
    sEl.style.fontSize = Math.floor(sSize) + "px";
    sEl.style.top = (plinthTop + B * 2 + 14) + "px";
  } else {
    sEl.style.display = "none";
  }

  // --- dust particles for the slam
  var dWrap = document.getElementById("tt-dust"), dust = [];
  for (var i = 0; i < 14; i++) {
    var p = document.createElement("div");
    p.className = "tt-dust";
    var side = i % 2 ? 1 : -1;
    p.style.left = (W / 2 + side * (titleW / 2) * (0.3 + rnd() * 0.7) - 5) + "px";
    p.style.top = (plinthTop - 6) + "px";
    p.style.background = i % 3 ? "var(--paper)" : "var(--accent)";
    dWrap.appendChild(p);
    dust.push({ el: p, dx: side * (30 + rnd() * 110), dy: -(30 + rnd() * 70), rot: (rnd() - 0.5) * 360 });
  }

  var tl = gsap.timeline({ paused: true });
  // 1) blocks rain in and stack (0 - 0.9s)
  blocks.forEach(function (b, i) {
    var t = targets[i];
    tl.fromTo(b, { x: t.dx, y: t.dy, rotation: t.rot, scale: 0.6 },
      { x: 0, y: 0, rotation: 0, scale: 1, duration: 0.36, ease: "back.out(1.5)" }, 0.02 + t.delay);
  });
  // 2) title slams (0.95s)
  var SLAM = 0.95;
  tl.fromTo(tEl, { scale: 3.2, opacity: 0, y: -30 }, { scale: 1, opacity: 1, y: 0, duration: 0.16, ease: "power4.in" }, SLAM);
  var hit = SLAM + 0.16;
  tl.fromTo("#tt-shake", { x: 0, y: 0 }, {
    keyframes: [{ x: -9, y: 6 }, { x: 8, y: -5 }, { x: -6, y: 3 }, { x: 4, y: -2 }, { x: 0, y: 0 }],
    duration: 0.26, ease: "none"
  }, hit);
  tl.to(blocks, { y: 7, duration: 0.06, ease: "power2.out", stagger: { each: 0.008, from: "center" } }, hit);
  tl.to(blocks, { y: 0, duration: 0.2, ease: "back.out(3)", stagger: { each: 0.008, from: "center" } }, hit + 0.06);
  tl.fromTo(tEl, { scaleY: 1 }, { keyframes: [{ scaleY: 0.86, scaleX: 1.08 }, { scaleY: 1.04, scaleX: 0.98 }, { scaleY: 1, scaleX: 1 }], duration: 0.24, ease: "none" }, hit);
  dust.forEach(function (p) {
    tl.fromTo(p.el, { x: 0, y: 0, rotation: 0, opacity: 1, scale: 1 },
      { x: p.dx, rotation: p.rot, duration: 0.55, ease: "power2.out" }, hit);
    tl.to(p.el, { keyframes: [{ y: p.dy, duration: 0.22, ease: "power2.out" }, { y: p.dy + 90, opacity: 0, scale: 0.4, duration: 0.33, ease: "power2.in" }] }, hit);
  });
  // 3) subtitle tag
  if (sub) {
    tl.fromTo(sEl, { xPercent: -50, scale: 0, rotation: -12 }, { xPercent: -50, scale: 1, rotation: -3, duration: 0.3, ease: "back.out(2.6)" }, hit + 0.18);
  }
  // 4) exit
  var out = d.duration - 0.32;
  tl.to(tEl, { scale: 0, opacity: 0, duration: 0.2, ease: "back.in(2)" }, out);
  if (sub) tl.to(sEl, { scale: 0, duration: 0.16, ease: "back.in(2)" }, out);
  blocks.forEach(function (b, i) {
    tl.to(b, { y: H * 0.7, rotation: targets[i].rot * 0.4, duration: 0.3, ease: "power3.in" }, out + 0.02 + (i % 7) * 0.012);
  });
  return tl;
});
