MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var rnd = MC.rng(7);
  var chan = String(v.channel_name || "").trim();
  var label = String(v.label || "SUBSCRIBE").toUpperCase();
  var done = String(v.done_label || "SUBSCRIBED").toUpperCase();

  var SC = d.vertical ? 1.15 : 1;
  var BH = Math.round(58 * SC);
  var fs = Math.round(26 * SC);
  var BW = Math.round(Math.max(label.length, done.length) * fs * 0.66 + 48 * SC);
  var BELL = BH + 6;

  var btn = document.getElementById("sb-btn");
  btn.style.width = BW + "px"; btn.style.height = BH + "px";
  ["sb-txt", "sb-txt-on"].forEach(function (id, i) {
    var el = document.getElementById(id);
    el.textContent = i ? done : label;
    el.style.fontSize = fs + "px";
    el.style.marginTop = (-fs * 0.5) + "px";
  });
  var bb = document.getElementById("sb-bellbox");
  bb.style.width = BELL + "px"; bb.style.height = BELL + "px";
  var bellPx = Math.max(2, Math.floor((BELL - 16) / 14));
  var bell = document.getElementById("sb-bell");
  bell.innerHTML = MC.pixelSVG([
    "......kk......",
    ".....kggk.....",
    "....klggdk....",
    "...klgggddk...",
    "...klgggddk...",
    "...klgggddk...",
    "..klggggdddk..",
    "..klggggdddk..",
    ".klgggggddddk.",
    "kllggggggddddk",
    "kkkkkkkkkkkkkk",
    ".....kddk.....",
    "......kk......"
  ], { k: "#000000", g: MC.css("--gold") || "#FFCC33", l: "#FFF2B0", d: "#C98F12" }, bellPx);

  // ring marks either side of the bell
  var rings = document.getElementById("sb-rings"), ringEls = [];
  [[-1, 0.28], [-1, 0.56], [1, 0.28], [1, 0.56]].forEach(function (r) {
    var e = document.createElement("div");
    e.className = "sb-ring";
    e.style.width = "12px"; e.style.height = "7px";
    e.style.left = (r[0] < 0 ? -18 : BELL + 2) + "px";
    e.style.top = (BELL * r[1]) + "px";
    rings.appendChild(e); ringEls.push(e);
  });

  var rowW = BW + 14 + BELL + 6;
  var chanEl = document.getElementById("sb-chan");
  var chanSize = Math.floor(Math.min(30 * SC, rowW / (Math.max(chan.length + 1, 1) * 0.53)));
  chanEl.textContent = chan ? "@" + chan.replace(/^@/, "").toUpperCase() : "";
  chanEl.style.fontSize = chanSize + "px";
  chanEl.style.top = "0px";
  var row = document.getElementById("sb-row");
  var rowTop = chan ? chanSize + 16 : 0;
  row.style.top = rowTop + "px";
  var g = document.getElementById("sb-group");
  var gH = rowTop + BELL;
  g.style.width = rowW + "px"; g.style.height = gH + "px";
  var gx = (W - rowW) / 2, gy = d.vertical ? H * 0.6 : H - gH - 56;
  g.style.left = gx + "px"; g.style.top = gy + "px";

  // cursor (pixel arrow), positioned in stage coords
  var cur = document.getElementById("sb-cursor");
  cur.innerHTML = MC.pixelSVG([
    "k..........", "kk.........", "kwk........", "kwwk.......", "kwwwk......", "kwwwwk.....",
    "kwwwwwk....", "kwwwwwwk...", "kwwwwwwwk..", "kwwwwwwwwk.", "kwwwwwkkkkk", "kwwkwwk....",
    "kwk.kwwk...", "kk..kwwk...", "k....kwwk..", ".....kwwk..", "......kk..."
  ], { k: "#000000", w: "#FFFFFF" }, Math.round(3 * SC));
  var btnCx = gx + BW * 0.62, btnCy = gy + rowTop + BH * 0.55;
  var bellCx = gx + BW + 14 + BELL * 0.55, bellCy = btnCy;

  // click burst bits
  var bits = document.getElementById("sb-bits"), bitEls = [];
  for (var i = 0; i < 10; i++) {
    var b = document.createElement("div");
    b.className = "sb-bit";
    b.style.left = (BW * 0.5 - 5) + "px"; b.style.top = (rowTop + BH / 2 - 5) + "px";
    b.style.background = ["var(--gold)", "var(--paper)", "var(--accent)", "var(--diamond)"][i % 4];
    bits.appendChild(b);
    var a = (i / 10) * Math.PI * 2 + rnd() * 0.4;
    bitEls.push({ el: b, x: Math.cos(a) * (BW * 0.45 + rnd() * 40), y: Math.sin(a) * (BH * 0.9 + rnd() * 30) });
  }

  var tl = gsap.timeline({ paused: true });
  // initial hidden states (owned by the timeline so seeking backwards is safe)
  tl.set(["#sb-face-on", "#sb-txt-on"], { opacity: 0 }, 0);
  tl.set("#sb-txt", { opacity: 1 }, 0);
  tl.set(ringEls, { scale: 0, opacity: 0 }, 0);
  tl.set(bitEls.map(function (b) { return b.el; }), { opacity: 0 }, 0);
  // pop in
  tl.fromTo(g, { y: 80, scale: 0.5, opacity: 0 }, { y: 0, scale: 1, opacity: 1, duration: 0.36, ease: "back.out(2.2)" }, 0);
  tl.fromTo(chanEl, { y: 20, opacity: 0 }, { y: 0, opacity: 1, duration: 0.24, ease: "back.out(2)" }, 0.16);
  // cursor glides in from bottom-right
  tl.fromTo(cur, { x: W + 40, y: H + 40 }, { x: btnCx, y: btnCy, duration: 0.6, ease: "power3.out" }, 0.4);
  // click 1: press the button
  var C1 = 1.05;
  tl.to(cur, { scale: 0.82, duration: 0.06, ease: "power2.out" }, C1);
  tl.to(cur, { scale: 1, duration: 0.12, ease: "back.out(3)" }, C1 + 0.08);
  tl.to(btn, { y: 4, duration: 0.05, ease: "power2.out" }, C1);
  tl.set(["#sb-face-on", "#sb-txt-on"], { opacity: 1 }, C1 + 0.05);
  tl.set("#sb-txt", { opacity: 0 }, C1 + 0.05);
  tl.to(btn, { y: 0, duration: 0.18, ease: "back.out(3)" }, C1 + 0.14);
  tl.fromTo(btn, { scale: 1 }, { keyframes: [{ scale: 1.1 }, { scale: 1 }], duration: 0.26, ease: "power1.inOut", immediateRender: false }, C1 + 0.12);
  bitEls.forEach(function (b) {
    tl.fromTo(b.el, { x: 0, y: 0, opacity: 1, scale: 1 }, { x: b.x, y: b.y, opacity: 0, scale: 0.3, duration: 0.5, ease: "power2.out", immediateRender: false }, C1 + 0.06);
  });
  // cursor to the bell, click 2
  tl.to(cur, { x: bellCx, y: bellCy, duration: 0.36, ease: "power3.inOut" }, 1.45);
  var C2 = 1.86;
  tl.to(cur, { scale: 0.82, duration: 0.06 }, C2);
  tl.to(cur, { scale: 1, duration: 0.12, ease: "back.out(3)" }, C2 + 0.08);
  tl.fromTo(bell, { rotation: 0 }, {
    keyframes: [{ rotation: 26 }, { rotation: -22 }, { rotation: 17 }, { rotation: -12 }, { rotation: 7 }, { rotation: -3 }, { rotation: 0 }],
    duration: 0.8, ease: "none", immediateRender: false
  }, C2 + 0.04);
  tl.to(bb, { keyframes: [{ scale: 1.15 }, { scale: 1 }], duration: 0.24 }, C2 + 0.02);
  tl.to(ringEls, { scale: 1, opacity: 1, duration: 0.08, stagger: 0.04 }, C2 + 0.08);
  tl.to(ringEls, { x: function (i) { return i < 2 ? -8 : 8; }, duration: 0.5, ease: "power2.out" }, C2 + 0.08);
  tl.to(ringEls, { opacity: 0, duration: 0.2 }, C2 + 0.6);
  // cursor leaves, then the group exits
  tl.to(cur, { x: W + 60, y: bellCy - 80, duration: 0.4, ease: "power3.in" }, 2.85);
  tl.to(g, { scale: 0, opacity: 0, duration: 0.26, ease: "back.in(2)" }, d.duration - 0.3);
  return tl;
});

