input.content:
#es-scrim { position: absolute; inset: 0; background: var(--ink); opacity: 0; }
#es-deco { position: absolute; inset: 0; }
#es-title { position: absolute; left: 0; width: 100%; text-align: center; color: var(--accent); line-height: 1; white-space: nowrap; }
#es-tag { position: absolute; left: 0; width: 100%; text-align: center; color: var(--paper); line-height: 1; white-space: nowrap;
  text-shadow: 2px 2px 0 #000; }
/* Video placeholder: the rectangle itself is EMPTY (transparent); the border sits outside it. */
.es-frame { position: absolute; outline: 5px solid var(--paper); outline-offset: 0;
  box-shadow: 0 0 0 9px #000, 9px 11px 0 9px rgba(0,0,0,0.5); }
.es-frame .es-corner { position: absolute; width: 18px; height: 18px; background: var(--accent); border: 3px solid #000; }
.es-label {
  position: absolute; left: -9px; bottom: 100%; margin-bottom: 14px;
  background: var(--accent); color: var(--ink); border: 3px solid #000; line-height: 1; white-space: nowrap;
  box-shadow: inset 3px 3px 0 rgba(255,255,255,0.35), inset -3px -3px 0 rgba(0,0,0,0.25), 4px 4px 0 #000;
}
.es-circle { position: absolute; border-radius: 50%; border: 5px solid var(--paper);
  box-shadow: 0 0 0 4px #000, inset 0 0 0 4px #000; }
.es-sublabel { position: absolute; top: 50%; white-space: nowrap; color: var(--paper); line-height: 1; }
.es-block { position: absolute; }

