MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var rnd = MC.rng(2024);
  var name = String(v.channel_name || "").toUpperCase();
  var tag = String(v.tagline || "");
  var scrim = Math.max(0, Math.min(1, MC.num(v.scrim, 0.62)));
  var K = 0.53;

  // Layout in logical px (x2 in the full render). Landscape rectangles match template.json layout_1920x1080.
  var L = d.vertical
    ? { title: [0, 70], titleMax: 76, tagY: 0, vl: [40, 250, 460, 259], vr: [40, 590, 460, 259], sub: [270, 905, 110] }
    : { title: [0, 34], titleMax: 64, tagY: 0, vl: [50, 170, 380, 214], vr: [530, 170, 380, 214], sub: [480, 470, 120] };

  var tEl = document.getElementById("es-title");
  var tSize = Math.floor(Math.min(L.titleMax, (W * 0.8) / (Math.max(name.length, 1) * K)));
  tEl.style.fontSize = tSize + "px";
  tEl.style.top = L.title[1] + "px";
  var parts = MC.renderLines(tEl, [name], { chars: true });
  var tgEl = document.getElementById("es-tag");
  var tgSize = Math.floor(Math.min(d.vertical ? 20 : 17, (W * 0.85) / (Math.max(tag.length, 1) * 0.55)));
  tgEl.textContent = tag; tgEl.style.fontSize = tgSize + "px";
  tgEl.style.top = (L.title[1] + tSize * 1.12) + "px";
  if (!tag) tgEl.style.display = "none";

  function place(el, r) {
    el.style.left = r[0] + "px"; el.style.top = r[1] + "px"; el.style.width = r[2] + "px"; el.style.height = r[3] + "px";
  }
  var vl = document.getElementById("es-vl"), vr = document.getElementById("es-vr");
  place(vl, L.vl); place(vr, L.vr);
  [[vl, v.left_label], [vr, v.right_label]].forEach(function (p) {
    var lab = p[0].querySelector(".es-label"), txt = String(p[1] || "").toUpperCase();
    lab.textContent = txt;
    var fs = d.vertical ? 22 : 18;
    lab.style.fontSize = fs + "px";
    lab.style.padding = Math.round(fs * 0.3) + "px " + Math.round(fs * 0.45) + "px " + Math.round(fs * 0.1) + "px";
    if (!txt) lab.style.display = "none";
    [[-1, -1], [1, -1], [-1, 1], [1, 1]].forEach(function (c) {
      var k = document.createElement("div");
      k.className = "es-corner";
      k.style[c[0] < 0 ? "left" : "right"] = "-20px";
      k.style[c[1] < 0 ? "top" : "bottom"] = "-20px";
      p[0].appendChild(k);
    });
  });
  var sub = document.getElementById("es-sub");
  var R = L.sub[2];
  place(sub, [L.sub[0] - R / 2, L.sub[1] - R / 2, R, R]);
  var sl = sub.querySelector(".es-sublabel");
  var slSize = d.vertical ? 24 : 20;
  sl.style.fontSize = slSize + "px";
  sl.style.marginTop = (-slSize / 2) + "px";
  if (d.vertical) { sl.style.right = "100%"; sl.style.marginRight = "22px"; }
  else { sl.style.left = "100%"; sl.style.marginLeft = "24px"; }

  // decorative blocks drifting in the empty corners
  var deco = document.getElementById("es-deco"), decos = [];
  var spots = d.vertical
    ? [[30, 140, 30], [490, 170, 24], [60, 880, 26], [470, 870, 32]]
    : [[60, 470, 28], [880, 455, 34], [300, 492, 20], [690, 500, 22]];
  var cols = ["var(--grass)", "var(--diamond)", "var(--amethyst)", "var(--redstone)"];
  spots.forEach(function (s, i) {
    var b = document.createElement("div");
    b.className = "mc-block es-block";
    b.style.left = s[0] + "px"; b.style.top = s[1] + "px"; b.style.width = s[2] + "px"; b.style.height = s[2] + "px";
    b.style.setProperty("--bc", cols[i % cols.length]);
    deco.appendChild(b); decos.push(b);
  });

  var tl = gsap.timeline({ paused: true });
  tl.fromTo("#es-scrim", { opacity: 0 }, { opacity: scrim, duration: 0.4, ease: "power1.out" }, 0);
  tl.fromTo(parts.chars, { y: -120, opacity: 0, rotation: function () { return (rnd() - 0.5) * 60; } },
    { y: 0, opacity: 1, rotation: 0, duration: 0.42, ease: "bounce.out", stagger: 0.045 }, 0.15);
  if (tag) tl.fromTo(tgEl, { y: 16, opacity: 0 }, { y: 0, opacity: 1, duration: 0.3, ease: "power3.out" }, 0.65);
  tl.fromTo(vl, { scale: 0.4, opacity: 0, rotation: -6 }, { scale: 1, opacity: 1, rotation: 0, duration: 0.4, ease: "back.out(2)" }, 0.45);
  tl.fromTo(vr, { scale: 0.4, opacity: 0, rotation: 6 }, { scale: 1, opacity: 1, rotation: 0, duration: 0.4, ease: "back.out(2)" }, 0.57);
  tl.fromTo(sub, { scale: 0, rotation: -180 }, { scale: 1, rotation: 0, duration: 0.45, ease: "back.out(2.2)" }, 0.75);
  tl.fromTo(sl, { opacity: 0, x: d.vertical ? 20 : -20 }, { opacity: 1, x: 0, duration: 0.25, ease: "power3.out" }, 1.0);
  tl.fromTo(decos, { scale: 0 }, { scale: 1, duration: 0.3, ease: "back.out(3)", stagger: 0.08 }, 0.9);
  // idle bob on decor blocks for the rest of the hold (finite)
  var start = 1.4, cyc = 1.6, reps = Math.max(0, Math.floor((d.duration - start) / cyc) - 1);
  decos.forEach(function (b, i) {
    tl.fromTo(b, { y: 0, rotation: 0 }, { y: -10, rotation: i % 2 ? 8 : -8, duration: cyc / 2, ease: "sine.inOut", yoyo: true, repeat: reps * 2 + 1, immediateRender: false }, start + i * 0.1 > d.duration - cyc ? start : start + i * 0.1);
  });
  // gentle pulse on the subscribe ring label every cycle
  tl.fromTo(sl, { scale: 1 }, { scale: 1.08, duration: cyc / 2, ease: "sine.inOut", yoyo: true, repeat: reps * 2 + 1, immediateRender: false }, start);
  return tl;
});

