input.content:
MC.define(function (S) {
  var v = S.v, d = S.d, W = d.w, H = d.h;
  var color = String(v.color || "#B072FF");
  var label = String(v.label || "").trim().toUpperCase();
  var dark = MC.shade(color, -0.18), light = MC.shade(color, 0.08);

  // block grid (60px logical = 120px in the full render); +2px overlap so no seams at full cover
  var B = 60;
  var cols = Math.ceil(W / B), rows = Math.ceil(H / B);
  var grid = document.getElementById("ms-grid"), cells = [], order = [];
  for (var r = 0; r < rows; r++) {
    for (var c = 0; c < cols; c++) {
      var e = document.createElement("div");
      e.className = "ms-b";
      e.style.left = (c * B - 1) + "px"; e.style.top = (r * B - 1) + "px";
      e.style.width = (B + 2) + "px"; e.style.height = (B + 2) + "px";
      e.style.background = (r + c) % 2 ? dark : light;
      grid.appendChild(e); cells.push(e); order.push(c + r);   // diagonal wave index
    }
  }
  var maxD = cols + rows - 2;

  var lab = document.getElementById("ms-label");
  if (label) {
    var size = Math.floor(Math.min(d.vertical ? 72 : 96, (W * 0.86) / (label.length * 0.53)));
    lab.textContent = label;
    lab.style.fontSize = size + "px";
    lab.style.top = (H / 2 - size / 2) + "px";
    lab.style.color = MC.onColor(color, "#121315", "#F4F1E8");
    if (MC.luma(color) > 0.55) lab.style.setProperty("--ol", "#F4F1E8");
  } else {
    lab.style.display = "none";
  }

  var IN = 0.11, SPREAD = 0.15;     // all covered by IN + SPREAD = 0.26s
  var OUT_AT = 0.32;                // clear 0.32 -> 0.58s
  var tl = gsap.timeline({ paused: true });
  tl.fromTo(cells, { scale: 0, rotation: -30 }, {
    scale: 1, rotation: 0, duration: IN, ease: "power3.out",
    stagger: function (i) { return (order[i] / maxD) * SPREAD; }
  }, 0);
  tl.to(cells, {
    scale: 0, rotation: 30, duration: IN, ease: "power3.in",
    stagger: function (i) { return (order[i] / maxD) * SPREAD; }
  }, OUT_AT);
  if (label) {
    tl.fromTo(lab, { scale: 1.9, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.12, ease: "power4.out" }, 0.1);
    tl.to(lab, { scale: 0.7, opacity: 0, duration: 0.12, ease: "power3.in" }, 0.42);
  }
  return tl;
});

