  /* Ink or paper, whichever reads on top of colour c */
  MC.onColor = function (c, ink, paper) { return MC.luma(c) > 0.55 ? ink : paper; };'''
new='''  MC.luma = function (c) { var r = hexToRgb(c); return (0.2126 * r[0] + 0.7152 * r[1] + 0.0722 * r[2]) / 255; };
  /* WCAG relative luminance + contrast ratio */
